// E2E2 continuous customer journey walkthrough — staging verification pass.
// Ad hoc script, deleted after the run. Lives under /opt/nxeon-v2 for module resolution.
import { chromium } from "playwright";
import { mkdirSync, writeFileSync, appendFileSync } from "node:fs";

const BASE = "https://staging.nxeon.cloud";
const OUT = "/tmp/claude-0/-/a847f019-50a6-4b60-bcba-1133f2a3ca8a/scratchpad";
mkdirSync(OUT, { recursive: true });
const LOG = `${OUT}/e2e2-console-network.log`;
writeFileSync(LOG, `=== E2E2 run start ${new Date().toISOString()} ===\n`);
const log = (msg) => { console.log(msg); appendFileSync(LOG, msg + "\n"); };

const RAND = Math.random().toString(36).slice(2, 10);
const EMAIL = `nx-e2e-${RAND}@example.com`;
const PASSWORD = "TestPass123!";
const NAME = "NX E2E Tester";
writeFileSync(`${OUT}/e2e2-creds.json`, JSON.stringify({ EMAIL, PASSWORD, NAME }, null, 2));
log(`Test account: ${EMAIL} / ${PASSWORD}`);

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 960 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();

page.on("console", (msg) => {
  if (["error", "warning"].includes(msg.type())) {
    log(`[CONSOLE:${msg.type()}] ${msg.text()}`);
  }
});
page.on("pageerror", (err) => log(`[PAGEERROR] ${err.message}`));
page.on("response", (res) => {
  const status = res.status();
  if (status >= 400) log(`[HTTP ${status}] ${res.request().method()} ${res.url()}`);
});
page.on("requestfailed", (req) => log(`[REQFAILED] ${req.method()} ${req.url()} - ${req.failure()?.errorText}`));

async function shot(name) {
  await page.waitForTimeout(500);
  const p = `${OUT}/${name}.png`;
  await page.screenshot({ path: p, fullPage: true });
  log(`screenshot -> ${p}`);
}

const STEP = process.env.E2E_STEP || "all";

try {
  // ---------- STEP 1: REGISTER ----------
  log("\n=== STEP 1: REGISTER ===");
  await page.goto(`${BASE}/register`, { waitUntil: "networkidle", timeout: 30000 });
  await shot("e2e2-01-register-page");

  await page.fill('input[name="name"]', NAME);
  await page.fill('input[name="email"]', EMAIL);
  await page.fill('input[name="password"]', PASSWORD);
  await shot("e2e2-01b-register-filled");

  await Promise.all([
    page.waitForURL((u) => !u.pathname.includes("/register"), { timeout: 30000 }).catch(() => {}),
    page.click('button[type="submit"]'),
  ]);
  await page.waitForTimeout(2000);
  log(`After register submit, URL = ${page.url()}`);
  await shot("e2e2-02-after-register");

  await ctx.storageState({ path: `${OUT}/e2e2-state.json` });
  log("Saved storage state after registration.");

} catch (e) {
  log(`FATAL in step 1: ${e.stack || e}`);
}

await browser.close();
log("\n=== Browser closed after step 1 ===");

