/* Data for the VPS deploy wizard.
 *
 * The one rule this file exists to keep: every number the wizard can display is
 * computed HERE, by the same functions that charge the card, and handed down
 * already worked out. The view prints; it never multiplies.
 *
 * `effectiveMonthlyCents` is built as a plan x term MATRIX rather than sent as a
 * rate plus a discount percent. Sending the percent would mean the browser does
 * `rate * (1 - pct)` — a second pricing formula, and the one that is on screen
 * when the customer decides. Terms are few and plans are few, so the matrix is
 * cheap and it cannot drift from `vpsTermPriceCents`.
 */

/* Icon per image, keyed off the platform's own `family` value rather than
   sniffing the display name. Control panels and applications have families too
   (cpanel, plesk, docker, ...), so one map serves all three tabs. */
const ICON_BY_FAMILY: Record<string, string> = {
  ubuntu: "ubuntu", debian: "debian", almalinux: "osA", rocky: "osC",
  arch: "arch", fedora: "osB", windows: "windows", centos: "osA",
  docker: "docker", wordpress: "cloud", node: "nginx", nginx: "nginx",
  mysql: "mysql", postgres: "postgres", redis: "redis",
  cpanel: "gear2", plesk: "gear2", webmin: "sliders", hestiacp: "sliders",
  cloudpanel: "sliders", cyberpanel: "sliders", aapanel: "sliders",
};
function osIcon(family: string, category: string): string {
  return ICON_BY_FAMILY[family?.toLowerCase()]
    ?? (category === "CONTROL_PANEL" ? "sliders" : category === "APPLICATION" ? "cube" : "linux");
}

export default async function NxDeployPage() {
  const user = await requireUser();

  // Real, per-customer eligibility for the first-month-free hosting promo —
  // NOT a display detail, the exact same advisory pre-check
  // lib/actions-hosting.ts runs before the atomic claim at charge time. The
  // wizard's hosting/email price was a flat, precomputed matrix with zero
  // per-user awareness (deliberately: "so there is no round-trip to make"),
  // which is why the promo's own plan-card badge ("First month free") and
  // the wizard's actual total disagreed — the matrix could not have known
  // whether THIS customer still qualifies. One extra check here, resolved
  // alongside the rest of this page's own data fetching.
  const hostingPromoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
  const hostingPromoEligible =
    firstMonthFreeAppliesTo("HOSTING") &&
    (await firstMonthFreeEnabled()) &&
    (await firstMonthFreeEligible(user.id, hostingPromoIpHash));

  const [plans, oses, nodes, gamePlans, hostingPlans, emailPlans, annualPct, diskPerGbCents, ipCents, backupCents] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
    /* All three categories — the design's Server settings panel has a tab per
       category (Operating system / Control panels / Applications), which is
       exactly what ImageCategory already distinguishes. They are separated in
       the VIEW, not filtered out here: a game-server image is a real thing you
       can deploy, it just is not an answer to "pick an operating system". */
    /* Game images are EXCLUDED from the VPS wizard. They are real deployable
       images, but Nxeon sells game servers as their own product with their own
       plans, panel and pricing — offering "Minecraft Server" as a VPS
       application sells the same thing twice, at the wrong price, without the
       game panel. Identified by `family` against the platform's own
       GAME_FAMILIES registry rather than by matching "... Server" in a name. */
    db.osTemplate.findMany({
      where: { active: true, NOT: { family: { in: [...GAME_FAMILIES] } } },
      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
    }),
    // enabled only — a disabled node is not a place we can provision.
    db.node.findMany({ where: { enabled: true }, select: { id: true, region: true } }),
    // "from" prices for the service tiles — the cheapest live plan of each kind,
    // read from the same tables the order path prices against.
    // Every active tier: the wizard groups them into families itself, so one
    // query serves both the "from" price on the tiles and the tier picker.
    db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
    db.hostingPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
    annualDiscountPct(),
    extraDiskPerGbCents(),
    dedicatedIpMonthlyCents(),
    backupPlusMonthlyCents(),
  ]);

